    /**
     * The typical HTTP status and the retry class of a documented code; null for a code this SDK
     * version does not know.
     */
    public static function info(string $code): ?ErrorCodeInfo
    {
        $info = self::INFO[$code] ?? null;

        return $info === null ? null : new ErrorCodeInfo($info[0], RetryClass::from($info[1]));
    }
